on conflict (id) do update set name_key = excluded.name_key, title = excluded.title,
  description = excluded.description, duration_min = excluded.duration_min, sets = excluded.sets,
  repetitions = excluded.repetitions, video_url = excluded.video_url, locale = excluded.locale, i18n = excluded.i18n,
  owner_tenant_id = null, archived = false, updated_at = now();

update athlete.plan_item i set title = e.title, description = e.description, i18n = e.i18n
  from athlete.exercise e
 where i.exercise_id = e.id and i.owner_tenant_id is null
   and (i.title, i.description, i.i18n) is distinct from (e.title, e.description, e.i18n);

alter table athlete.exercise force row level security;
alter table athlete.plan_item force row level security;
